def source(n):
    for i in range(n):
        yield i

def filter_pos(nums):
    for x in nums:
        if x > 0:
            yield x

def map_sq(nums):
    for x in nums:
        yield x * x

def reduce_sum(nums):
    total = 0
    for x in nums:
        total += x
    return total

def pipeline(n):
    return reduce_sum(map_sq(filter_pos(source(n))))

print(pipeline(1_000_000))

