import os

def search_logs(directory, severity, stop_after=None):
    matches = 0
    for filename in os.listdir(directory):
        path = os.path.join(directory, filename)
        if not os.path.isfile(path):
            continue
        with open(path, 'r') as file:
            for line in file:
                if severity in line:
                    yield line.strip()
                    matches += 1
                    if stop_after is not None and matches >= stop_after:
                        return

